const crypto = require('crypto');
const secret = $env.WEBHOOK_HMAC_SECRET;
const base = $env.CONVEX_SITE_URL?.replace(/\/$/, '');
if (!secret || !base) throw new Error('WEBHOOK_HMAC_SECRET and CONVEX_SITE_URL required');

const now = new Date();
const today = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}-${String(now.getUTCDate()).padStart(2, '0')}`;
const pathWithQuery = `/automation/overdue-loans?today=${today}`;
const timestamp = String(Math.floor(Date.now() / 1000));
const message = `GET\n${pathWithQuery}\n${timestamp}`;
const signature = crypto.createHmac('sha256', secret).update(message).digest('hex');
const url = `${base}${pathWithQuery}`;
return [{ json: { url, signature, timestamp, today } }];

const row = $input.first().json;
try {
  if ($env.SIMULATE_DELIVERY_FAIL === '1') {
    throw new Error('Simulated delivery failure (SIMULATE_DELIVERY_FAIL)');
  }
  const email = (row.borrowerEmail ?? '').trim();
  if (!email) {
    throw new Error('Missing borrower email');
  }
  const line = `Overdue reminder — return "${row.toolName}" (was due ${row.endDate}). To: ${row.borrowerName} <${email}>`;
  console.log(line);
  return [{ json: { ...row, reminderStatus: 'sent' } }];
} catch (error) {
  const detail = error instanceof Error ? error.message : String(error);
  console.error('Overdue reminder failed:', detail);
  return [{ json: { ...row, reminderStatus: 'failed', detail } }];
}

const crypto = require('crypto');
const secret = $env.WEBHOOK_HMAC_SECRET;
const base = $env.CONVEX_SITE_URL?.replace(/\/$/, '');
const row = $input.first().json;
const status = row.reminderStatus === 'sent' ? 'sent' : 'failed';
const payload = {
  idempotencyKey: row.idempotencyKey,
  loanRequestId: row.loanRequestId,
  status,
};
if (status === 'failed' && row.detail) {
  payload.detail = row.detail;
}
const body = JSON.stringify(payload);
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');
return [{ json: { url: `${base}/automation/reminder-sent`, body, signature } }];
